        _, i, j, joined = best
        pieces[i] = joined
        del pieces[j]
        del mosaics[j]
        mosaics[i] = orientations(joined)

    piece = pieces[0]
    ph, pw = len(piece), len(piece[0])
    if ph > h or pw > w:
        # Crop to fit while retaining the center of the assembled picture.
        y0 = max(0, (ph - h) // 2)
